  expected: true,
},

{
  label: "文字の大きさは、90% より小さい段が無いことを null で答える",
  actual: () => TextSize.smaller(90) === null,
  expected: true,
},

{
  label: "文字の大きさ 110% は、倍率 1.1 として書く",
  actual: () => TextSize.ratioOf(110),
  expected: "1.1",
},

/**
 * 箱の図の欄(構造マップとテスト)を除き、どの画面のパネルと本文にも効く文字の大きさ。percent(整数)で持ち、`Steps` から選ぶ。開くたびに `Initial` から始める。
 *
 * 覚える形にはしない。全 PR で覚えるとブラウザの拡大と同じくほかのページにも効き、PR ごとに覚えても 1 つの PR のページは開く回数が少なく覚える価値が小さい。
 */
const TextSize = (() => {
  const Steps = Object.freeze([90, 100, 110, 120, 130, 140, 150]);
  const stepAfter = (percent, offset) => {
    const next = Steps[Steps.indexOf(percent) + offset];
    return next === undefined ? null : next;
  };
  return Object.freeze({
    Steps,
    Initial: 100,
    /**
     * @param percent 今の文字の大きさ
     * @returns 1 段大きい文字の大きさ。今が `Steps` の最大なら null
     */
    larger: (percent) => stepAfter(percent, 1),
    /**
     * @param percent 今の文字の大きさ
     * @returns 1 段小さい文字の大きさ。今が `Steps` の最小なら null
     */
    smaller: (percent) => stepAfter(percent, -1),
    /**
     * 文字の大きさを、CSS 変数 `--text-size-ratio` へ書く倍率にする。
     * @param percent 文字の大きさ
     * @returns 倍率の文字列(110 なら `"1.1"`)
     */
    ratioOf: (percent) => String(percent / 100),
  });
})();

const TopicScroll = (() => {
  // 読む線。本文の欄の CSS px で 140(見た目では 140 × 文字の倍率)。本文の末尾には「欄の高さ − 読む線」の余白を CSS で取ってあり(`.topic-body`)、どの節も読む線まで送れる。
  const ReadingLine = 140;
  /** 見た目の px での読む線の位置。 */
  const lineAt = (ratio) => ReadingLine * ratio;
  return Object.freeze({
    /**
     * 読む線(スクロールする領域の上端から、見た目で 140 × 倍率 px)より上に来た最後の節を、今の節にする。
     * @param tops 節の上端の、スクロールする領域の上端からの距離(見た目の px・節の順)
     * @param ratio 本文の欄に掛かっている文字の倍率
     * @returns 今の節の添字。上端が読む線(140 × 倍率 を含む)まで来た最後の節で、どれも来ていなければ最初の節。節が無ければ null
     */
    currentOf: (tops, ratio) => {
      if (tops.length === 0) return null;
      const passed = tops.findLastIndex((top) => top <= lineAt(ratio));
      return passed < 0 ? 0 : passed;
    },

/**
 * 倍率を変える前に読む線にあった今の節の点を、変えたあとの読む線へ置くときの、節の上端の位置を求める。
 * 点は節の高さに対する割合で持ち、読む線が節の下の隙間にあったときは節の下端(割合 1)にする。
 * @param before 変える前の節の上端(見た目の px)・高さ(見た目の px)・倍率
 * @param after 変えたあとの節の高さ(見た目の px)・倍率
 * @returns 変えたあとの節の上端の、スクロールする領域の上端からの距離(見た目の px)
 */
keptTopOf: ({ before, after }) => {
  const share = Math.min((lineAt(before.ratio) - before.top) / before.height, 1);
  return lineAt(after.ratio) - share * after.height;
},

keepReadingOf: ({ main, currentColumns }) => (apply) => {
  const article = currentColumns().currentArticle();
  if (article === null) {
    apply();
    return;
  }
  const area = readingAreaOf(main);
  const beforeRect = article.getBoundingClientRect();
  const before = { top: beforeRect.top - area.topOf(), height: beforeRect.height, ratio: textRatioOf(main) };
  apply();
  // ずらす量は apply 後の実測から取る。倍率から計算すると、幅が変わって折り返しが変わった分を取り込めない。
  const afterRect = article.getBoundingClientRect();
  const after = { height: afterRect.height, ratio: textRatioOf(main) };
  area.scrollBy(afterRect.top - area.topOf() - TopicScroll.keptTopOf({ before, after }), after.ratio);
  // ずらす量が 0 のときや、先頭・末尾で止まったときはスクロールのイベントが来ないので、ここで決め直す。
  currentColumns().follow(area.topOf(), after.ratio);
},
